@keyframes countdown {
0% {
transform: scale(0.5);
opacity: 0;
}
20% {
transform: scale(1.2);
opacity: 1;
}
40% {
transform: scale(1);
}
100% {
transform: scale(0.8);
opacity: 0;
}
}

@keyframes fade-in {
from {
opacity: 0;
transform: translateY(20px);
}
to {
opacity: 1;
transform: translateY(0);
}
}

.animate-countdown {
animation: countdown 1s ease-out forwards;
}

.animate-fade-in {
animation: fade-in 0.5s ease-out forwards;
}
